vector<long long> a;
long long fn(long long n, long long l) {
	long long num = n / a[l];
	n %= a[l];
  if(!n) {
    return num * l;
  }
  return num * l + min(l + fn(a[l] - n, l - 1), fn(n, l - 1));
}
